#include "MobileAccountProofHostBindingPrivate.hpp"
#include <map>
#include <memory>
#include <mutex>
#include <thread>
namespace ynx::core::mobile::registered {
namespace port=ynx::sdk::mobile::accountproof;namespace auth=ynx::auth::mobile::receipt;
struct CommittedAccountProof final {
 std::thread::id actor=std::this_thread::get_id();auth::OriginalEngineSource*source=nullptr;
 auth::OriginalAccountProofHost*host=nullptr;port::Reader*reader=nullptr;
 auth::EngineSelection selection;std::optional<Checkpoint>captured;
 Failure first,closeFailure;bool sourceHeld=false,retired=false,readerClose=false,hostClose=false,closeSelected=false,closed=false;
};
namespace {
std::mutex&mutex=*new std::mutex;auto&inventory=*new std::map<CommittedAccountProof*,std::unique_ptr<CommittedAccountProof>>;
CommittedAccountProof*known(CommittedAccountProof*p){std::lock_guard<std::mutex>l(mutex);auto i=inventory.find(p);return i==inventory.end()?nullptr:i->second.get();}
Failure converted(port::Failure f){return{f.present,f.code};}
void retain(Failure&first,Failure f){if(f.present&&!first.present)first=f;}
Failure invalid(){return{true,11601};}
Failure gate(CommittedAccountProof*p){if(!p||p->actor!=std::this_thread::get_id())return invalid();if(p->first.present)return p->first;if(p->retired||p->closed||p->closeSelected)return{true,11604};auto f=auth::originalEngineSourceCurrent(p->source);if(f.present){retain(p->first,f);return f;}f=converted(auth::originalAccountProofHostCurrent(p->host,p->source));if(f.present){retain(p->first,f);return f;}f=auth::originalEngineSourceCurrent(p->source);if(f.present)retain(p->first,f);return f;}
Registration record(const port::RegistrationDATA&r){return{r.algorithmVersion,r.owner,r.pkA,r.pkB,r.revision,r.registeredAt,r.activeFrom,r.ledgerNonce};}
AccountView account(const port::AccountDATA&a){AccountView out{a.owner,Bytes(a.networkID.begin(),a.networkID.end()),a.nativeChainID,(uint64_t)a.committedHeight,a.executionHeight,a.ledgerNonce,a.policyOriginal,a.committedAuthorizationStatus,a.authorizationStatus,a.committedPQSigningEnabled,a.pqSigningEnabled,{},{}};if(a.committedRegistration)out.committedRegistration=record(*a.committedRegistration);if(a.executionRegistration)out.executionRegistration=record(*a.executionRegistration);return out;}
Checkpoint checkpoint(const port::CheckpointDATA&c){return{c.chainID,(uint64_t)c.height,Bytes(c.appHash.begin(),c.appHash.end())};}
ReadResult classify(CommittedAccountProof*p,port::ReadOutcome r){/* The wire retains NotReady failure presence; it is a separate nonterminal
 readiness condition, never selected as p->first. */if(r.state==port::ReadState::NotReady){if(!r.failure.present){auto f=invalid();retain(p->first,f);return{false,f};}return{false,{},true,converted(r.failure)};}auto f=converted(r.failure);if(r.state!=port::ReadState::Ready&&!f.present)f=invalid();if(f.present){retain(p->first,f);return{false,f};}return{true,{}};}
ReadResult read(CommittedAccountProof*p,bool fresh,port::CommittedProofViewDATA&view){auto f=gate(p);if(f.present)return{false,f};auto result=fresh?port::current(p->reader,view):port::read(p->reader,view);auto state=classify(p,result);if(state.failure.present)return state;f=gate(p);if(f.present)return{false,f};if(!state.ready)return state;if(view.proof.height<=0||view.currentCheckpoint.height<0||view.historicalAccount.committedHeight<0||view.currentAccount.committedHeight<0||view.blockOriginal.empty()||view.successorOriginal.empty()||view.blockOriginal.size()>port::maxLightBlockBytes||view.successorOriginal.size()>port::maxLightBlockBytes||view.historicalAccount.policyOriginal.size()>port::maxPolicyBytes||view.currentAccount.policyOriginal.size()>port::maxPolicyBytes){f=invalid();retain(p->first,f);return{false,f};}auto c=checkpoint(view.proof);if(p->captured&&(p->captured->chainId!=c.chainId||p->captured->height!=c.height||p->captured->fullAppHash!=c.fullAppHash)){f=invalid();retain(p->first,f);return{false,f};}p->captured=c;return state;}
Failure drain(CommittedAccountProof*p){if(p->reader){if(!p->readerClose){p->readerClose=true;retain(p->closeFailure,converted(port::close(p->reader)));}if(!port::isClosed(p->reader))return{true,11606};auto f=converted(port::releaseClosed(p->reader));if(f.present){retain(p->closeFailure,f);return f;}p->reader=nullptr;}if(p->host){if(!p->hostClose){p->hostClose=true;retain(p->closeFailure,converted(auth::closeOriginalAccountProofHost(p->host)));}if(!auth::originalAccountProofHostClosed(p->host))return{true,11606};auto f=converted(auth::releaseClosedOriginalAccountProofHost(p->host));if(f.present){retain(p->closeFailure,f);return f;}p->host=nullptr;}if(p->sourceHeld){auto f=auth::releaseOriginalEngineSource(p->source);if(f.present){retain(p->closeFailure,f);return f;}p->sourceHeld=false;}p->closed=true;p->source=nullptr;return{};}
}
Acquisition acquireCommittedAccountProof(auth::OriginalEngineSource*source)noexcept{Acquisition out;try{auto owned=std::make_unique<CommittedAccountProof>();out.owner=owned.get();{std::lock_guard<std::mutex>l(mutex);inventory.emplace(out.owner,std::move(owned));}auto&p=*out.owner;p.source=source;auto f=auth::readOriginalEngineSelection(source,p.selection);if(f.present){p.first=f;out.failure=f;return out;}f=auth::retainOriginalEngineSource(source);if(f.present){p.first=f;out.failure=f;return out;}p.sourceHeld=true;auto host=auth::acquireOriginalAccountProofHost(source);p.host=host.owner;f=converted(host.failure);if(f.present){p.first=f;out.failure=f;return out;}if(!p.host){p.first=out.failure=invalid();return out;}port::HostPort*original=nullptr;f=converted(auth::readOriginalAccountProofHost(p.host,source,original));if(f.present||!original){p.first=out.failure=f.present?f:invalid();return out;}auto reader=port::open(original,source);p.reader=reader.owner;f=converted(reader.failure);if(f.present){p.first=out.failure=f;return out;}if(!p.reader){p.first=out.failure=invalid();return out;}f=gate(&p);if(f.present)out.failure=f;return out;}catch(...){out.failure=invalid();if(out.owner)out.owner->first=out.failure;return out;}}
ReadResult readCaptured(CommittedAccountProof*raw,CapturedPolicy&out)noexcept{auto*p=known(raw);try{port::CommittedProofViewDATA view;auto result=read(p,false,view);/* Preserve public original copies before interpreting late failure. */if(p&&view.proof.height>0)out={2,p->selection.platform,p->selection.engineReference,checkpoint(view.proof),account(view.historicalAccount),view.blockOriginal,view.successorOriginal};return result;}catch(...){auto f=invalid();if(p)retain(p->first,f);return{false,f};}}
ReadResult current(CommittedAccountProof*raw,Continuation&out)noexcept{auto*p=known(raw);try{port::CommittedProofViewDATA view;auto result=read(p,true,view);if(p&&view.proof.height>0)out={2,checkpoint(view.proof),checkpoint(view.currentCheckpoint),account(view.currentAccount)};return result;}catch(...){auto f=invalid();if(p)retain(p->first,f);return{false,f};}}
void retire(CommittedAccountProof*raw)noexcept{auto*p=known(raw);if(!p||p->actor!=std::this_thread::get_id())return;p->retired=true;if(p->reader)port::retire(p->reader);if(p->host)auth::retireOriginalAccountProofHost(p->host);}
Failure join(CommittedAccountProof*raw)noexcept{auto*p=known(raw);if(!p||p->actor!=std::this_thread::get_id())return invalid();Failure observed;if(p->reader){auto f=converted(port::join(p->reader));retain(p->closeFailure,f);retain(observed,f);}if(p->host){auto f=converted(auth::joinOriginalAccountProofHost(p->host));retain(p->closeFailure,f);retain(observed,f);}if(p->closeSelected&&!p->closed){auto f=drain(p);if(f.present)return f;}return observed;}
Failure close(CommittedAccountProof*raw)noexcept{auto*p=known(raw);if(!p||p->actor!=std::this_thread::get_id())return invalid();retire(p);if(p->closeSelected)return p->closeFailure;p->closeSelected=true;retain(p->closeFailure,p->first);retain(p->closeFailure,join(p));return p->closeFailure;}
bool isClosed(CommittedAccountProof*raw)noexcept{auto*p=known(raw);return p&&p->actor==std::this_thread::get_id()&&p->closed;}
Failure releaseClosed(CommittedAccountProof*raw)noexcept{auto*p=known(raw);return p&&p->actor==std::this_thread::get_id()&&p->closed?Failure{}:invalid();}
}
